function faqPage(){const faqs=[["What is NegosyoDepot?","NegosyoDepot helps people discover business packages, services, local fulfillment, and growth opportunities, then contact the relevant provider."],["How do I find a business or service?","Browse Explore, use Business Finder, or filter by category, budget, and location. Read the full listing and ask the seller for current terms, inclusions, permits, and total costs."],["How do I contact a seller or buyer?","Use the inquiry links on listings. NegosyoDepot is currently a discovery and matching preview; do not assume a conversation, identity, or transaction is verified unless the site clearly says so."],["Can I post a business package or service?","Use Post Business to prepare a listing. The current preview does not submit listings to a shared, moderated database. Confirm publication status before treating a draft as public."],["What is Looking for?","It is a request board for people seeking business packages, services, suppliers, fulfillment, investors, or financing. Requests in this preview are stored only in this browser and are not visible to other users."],["How do I engage with an investor or funder?","Review the funder’s identity, organization, authority, instrument, fees, risks, and written terms. Corporate registration alone does not prove authority to offer securities, lend, or solicit investments. Seek independent advice before committing."],["Does the platform handle or guarantee a deal?","NegosyoDepot and MarketplacePH are intended as discovery and matching platforms. They do not guarantee a user, listing, offer, job, outcome, or user conduct and are not a party to private agreements, subject to rights and liabilities that cannot be excluded under applicable law. Users must use discretion and due diligence."],["How do I report suspicious activity?","Save the listing URL and messages, stop sending money or sensitive documents, and contact platform support. For urgent threats or suspected crimes, contact the relevant Philippine authorities directly."]];return '<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / FAQ</div><div class="section-kicker">Help and safer connections</div><h1>Frequently asked questions</h1><p>Quick guidance for discovering opportunities and engaging responsibly with sellers, buyers, providers, and funders.</p><div class="hero-actions"><a class="btn btn-primary" href="#/looking-for">Looking for</a><a class="btn btn-outline" href="#/trust">Trust & safety</a></div></div></section><section class="section" style="padding-top:10px"><div class="container faq-list">'+faqs.map(([q,a])=>'<details class="faq-item"><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>').join('')+'</div></section><section class="section section-white" id="safety"><div class="container"><div class="section-head"><div><div class="section-kicker">Pause, verify, then proceed</div><h2>Scam and illegal recruitment reminders</h2></div><p>Listings and messages are not proof of identity, licensing, authority, or safety.</p></div><div class="feature-row"><article class="feature-card"><h3>Verify people and businesses</h3><p>Check organizations through official registries, call a number you find independently, meet safely, inspect the business, and ask for written terms and references. Avoid pressure, guaranteed returns, advance-fee demands, and payment to personal accounts.</p><a href="https://www.sec.gov.ph/investors-education-and-information/advisories/" target="_blank" rel="noopener noreferrer">Check SEC investor advisories →</a></article><article class="feature-card"><h3>Before investing or borrowing</h3><p>Confirm required SEC/BSP authority for the specific activity. SEC incorporation alone does not grant permission to sell securities, solicit investments, or lend. Review risks, effective costs, fees, collateral, repayment, and exit terms with independent counsel.</p><a href="https://appointment.sec.gov.ph/investors-education-and-information/investment-101/" target="_blank" rel="noopener noreferrer">Read SEC Investment 101 →</a></article><article class="feature-card"><h3>Before accepting an overseas job</h3><p>Verify the recruitment agency’s current license and job order directly with DMW. Do not use tourist visas for work or deal with fixers. Confirm lawful fees, a valid contract, and official receipt; be wary of guaranteed jobs and unusually high salaries.</p><a href="https://dmw.gov.ph/archives/v1/approved-job-orders" target="_blank" rel="noopener noreferrer">Verify DMW job orders →</a></article></div><div class="trust-note faq-disclaimer"><strong>Platform reminder:</strong> NegosyoDepot/MarketplacePH provides a place to discover and connect. Users are responsible for their own due diligence, communications, contracts, payments, and safety. The platform does not guarantee users or private dealings and is not a party to user-to-user transactions, subject to rights and liabilities that cannot lawfully be excluded.</div></div></section>'}
function lookingForPage(){const types=["Business package or franchise","Investor or funder","Loan or inventory finance","Professional service","Fulfillment or logistics","Supplier or distributor","Buyer or business partner","Other"];let rows=[];try{rows=JSON.parse(localStorage.getItem("nd_looking_for")||"[]")}catch{}return '<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#/">Home</a> / Looking for</div><div class="section-kicker">Describe the next thing your business needs</div><h1>Looking for the right business connection?</h1><p>Prepare a request for a business package, service, supplier, fulfillment partner, investor, funder, or financing option.</p><a class="btn btn-outline" href="#/faq?section=safety">Review safety guidance</a></div></section><section class="section" style="padding-top:8px"><div class="container looking-layout"><form class="panel looking-form" id="lookingForForm"><h2>Draft a request</h2><p>Share only details needed to assess fit. Do not include passwords, bank details, ID numbers, or confidential financial records.</p><div class="form-grid"><div class="field"><label for="lfType">What are you looking for?</label><select id="lfType" required>'+types.map(t=>'<option>'+esc(t)+'</option>').join('')+'</select></div><div class="field"><label for="lfLocation">Preferred location</label><input id="lfLocation" maxlength="100" placeholder="City, province, or Philippines-wide" required></div><div class="field full"><label for="lfTitle">Request title</label><input id="lfTitle" maxlength="100" placeholder="Looking for cold storage and delivery in Cebu" required></div><div class="field full"><label for="lfDetails">What do you need?</label><textarea id="lfDetails" rows="4" maxlength="1200" placeholder="Describe goals, timing, key requirements, and how a provider can respond." required></textarea></div><div class="field"><label for="lfBudget">Budget or funding range (optional)</label><input id="lfBudget" maxlength="80" placeholder="₱50,000–₱100,000 or open to proposals"></div><div class="field"><label for="lfContact">Contact preference</label><select id="lfContact"><option>Contact through the platform when available</option><option>Share business email after verification</option><option>Discuss after initial screening</option></select></div></div><label class="check-row"><input id="lfConsent" type="checkbox" required><span>I understand this preview saves the request only in this browser; it is not shared with other users.</span></label><button class="btn btn-primary" type="submit">Save request on this device</button><p id="lfStatus" class="fine-print" role="status"></p></form><aside class="panel"><div class="section-kicker">Before you post</div><h3>Make your request useful and safe</h3><ul><li>Describe the result, location, timing, and realistic range.</li><li>For funding, specify whether you seek debt, equity, inventory support, or another structure.</li><li>Keep contact details and sensitive documents private until you verify the other party.</li><li>Ask for written fees, scope, risks, and terms. Avoid advance fees to unlock a promised loan or investment.</li></ul><a class="link-arrow" href="#/faq?section=safety">See safety reminders →</a></aside></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="section-kicker">Saved in this browser</div><h2>Your request drafts</h2></div><button class="btn btn-outline" type="button" data-clear-looking-for>Clear drafts</button></div><div class="looking-list" id="lookingForList">'+lookingForCards(rows)+'</div></div></section>'}
function lookingForCards(rows){if(!rows.length)return '<div class="empty-state">Your saved request drafts will appear here on this device.</div>';return rows.map(x=>'<article class="looking-card"><span class="listing-badge">'+esc(x.type)+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.details)+'</p><div class="listing-meta"><span>⌖ '+esc(x.location)+'</span><span>'+(x.budget?esc(x.budget):'Budget not specified')+'</span></div><small>Private browser draft · '+esc(new Date(x.created).toLocaleDateString('en-PH'))+'</small><button class="btn btn-outline" type="button" data-delete-looking="'+esc(x.id)+'">Delete draft</button></article>').join('')}
function bindLookingForTools(){const form=document.getElementById('lookingForForm');if(form)form.addEventListener('submit',e=>{e.preventDefault();const x={id:String(Date.now()),type:document.getElementById('lfType').value,location:document.getElementById('lfLocation').value.trim(),title:document.getElementById('lfTitle').value.trim(),details:document.getElementById('lfDetails').value.trim(),budget:document.getElementById('lfBudget').value.trim(),created:new Date().toISOString()};try{const all=JSON.parse(localStorage.getItem('nd_looking_for')||'[]');all.unshift(x);localStorage.setItem('nd_looking_for',JSON.stringify(all.slice(0,50)));document.getElementById('lfStatus').textContent='Request saved on this device. It is private and has not been shared with other users.';form.reset();document.getElementById('lookingForList').innerHTML=lookingForCards(all.slice(0,50));bindLookingForDelete()}catch{document.getElementById('lfStatus').textContent='Could not save in this browser. Copy your request before leaving.'}});document.querySelector('[data-clear-looking-for]')?.addEventListener('click',()=>{localStorage.removeItem('nd_looking_for');document.getElementById('lookingForList').innerHTML=lookingForCards([])});bindLookingForDelete()}
function bindLookingForDelete(){document.querySelectorAll('[data-delete-looking]').forEach(b=>b.onclick=()=>{const all=JSON.parse(localStorage.getItem('nd_looking_for')||'[]').filter(x=>x.id!==b.dataset.deleteLooking);localStorage.setItem('nd_looking_for',JSON.stringify(all));document.getElementById('lookingForList').innerHTML=lookingForCards(all);bindLookingForDelete()})}

function enhanceHome(){if((location.hash.slice(1).split("?")[0]||"/")!=="/")return;const main=document.querySelector("#main");if(!main||main.querySelector(".home-looking-intro"))return;const block=document.createElement("section");block.className="section section-white home-looking-intro";block.innerHTML="<div class=\"container\"><div class=\"section-head\"><div><div class=\"section-kicker\">Need something specific?</div><h2>Post what you’re looking for.</h2></div><p>Tell the community what kind of business package, service, supplier, investor, or funding support you need.</p></div><div class=\"feature-row\"><article class=\"feature-card\"><div class=\"category-icon\">⌕</div><h3>Make a clear request</h3><p>Describe your goal, location, budget range, and timing so relevant providers can assess fit.</p><a class=\"link-arrow\" href=\"#/looking-for\">Explore requests and post yours →</a></article><article class=\"feature-card\"><div class=\"category-icon\">✓</div><h3>Check every offer</h3><p>Independently verify identities, authority, costs, terms, and references before sharing information or money.</p><a class=\"link-arrow\" href=\"#/faq?section=safety\">Read safety guidance →</a></article><article class=\"feature-card\"><div class=\"category-icon\">↗</div><h3>Find the right connection</h3><p>Requests can cover negosyo packages, professional services, fulfillment, suppliers, and funding.</p><a class=\"link-arrow\" href=\"#/looking-for\">Open Looking for →</a></article></div></div>";main.appendChild(block)}
window.addEventListener("DOMContentLoaded",()=>setTimeout(()=>{bindLookingForTools();enhanceHome()},0));
window.addEventListener("hashchange",()=>setTimeout(bindLookingForTools,0));

